function Deploy-WheelApp($app){
  Write-Host "🚀 DEPLOYING: $app to 5 ports!" -ForegroundColor Green
  $source="C:\BanglaHost\BuilderHub\projects\latest"; for($p=8881;$p -le 8885;$p++){ $dest="C:\BanglaHost\nginx\html\sites\port_$p\$app"; New-Item -ItemType Directory -Force -Path $dest | Out-Null; Copy-Item "$source\*" $dest -Recurse -Force -ErrorAction SilentlyContinue }
  "$app - http://localhost:8881/$app/ - $(Get-Date)" | Out-File "$wheelDir\marketplace.txt" -Append -Encoding utf8; Write-Host "✅ DEPLOYED: http://localhost:8881/$app/" -ForegroundColor Cyan
}
# MAIN WHEEL LOOP - If projectName given, deploy it, else invent new
if($projectName -ne ""){ Deploy-WheelApp $projectName } else {
  Write-Host "🧠 WHEEL BRAIN STARTED - Inventing every 30 mins for demo (8 apps/day in production)!" -ForegroundColor Magenta
